<?php require '../includes/functions.php';$g=null;if($_SERVER['REQUEST_METHOD']==='GET'&&!empty($_GET['tracking_number'])){$q=db()->prepare('SELECT tracking_number,title,status,created_at,updated_at FROM grievances WHERE tracking_number=?');$q->execute([strtoupper(trim($_GET['tracking_number']))]);$g=$q->fetch();}$pageTitle='Track grievance';require '../includes/header.php';?><section class="panel form-narrow"><h1>Track a grievance</h1><p>Enter the tracking number provided when the grievance was submitted. Public results show status only; sign in to see remarks and complete details.</p><form method="get"><label for="tracking">Tracking number</label><input id="tracking" name="tracking_number" required value="<?=e($_GET['tracking_number']??'')?>"><button>Search</button></form><?php if(isset($_GET['tracking_number'])):if($g):?><p><b>Title:</b> <?=e($g['title'])?></p><p><b>Status:</b> <?=e($g['status'])?></p><p><b>Last updated:</b> <?=e($g['updated_at'])?></p><?php else:?><p class="error">No grievance was found for that tracking number.</p><?php endif;endif?></section><?php require '../includes/footer.php';?>
